// Works with any prospect sheet: finds the email / subject / body / status / company columns by name.
const norm = k => k.toLowerCase().replace(/[^a-z0-9]/g, '');
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const rows = $input.all().map(i => i.json);
const headers = Object.keys(rows[0] || {});

const find = (test) => headers.find(h => test(norm(h)));
const statusCol  = find(n => n === 'status') || find(n => n.includes('status'));
const subjectCol = find(n => n === 'subject') || find(n => n.includes('subject'));
const bodyCol    = find(n => n === 'body') || find(n => n.includes('body')) || find(n => n === 'message' || n === 'emailcopy' || n === 'emailtext');
const companyCol = find(n => n === 'company') || find(n => n.includes('company') && !n.includes('size')) || find(n => n === 'name');
const emailCols  = headers.filter(h => { const n = norm(h); return n.includes('email') && !/(source|status|subject|body|verified|copy|text)/.test(n); });

const diagnostics = { rows_read: rows.length, headers_found: headers,
  detected: { email: emailCols, subject: subjectCol || null, body: bodyCol || null, status: statusCol || null, company: companyCol || null } };

if (!subjectCol || !bodyCol || emailCols.length === 0 || !statusCol) {
  return [{ json: { nothing_to_send: true, reason: 'Missing a required column. The sheet needs columns for email, subject, body and status (add an empty "Status" column if there is none).', ...diagnostics } }];
}

const getEmail = r => { for (const c of emailCols) { const v = String(r[c] ?? '').trim(); if (EMAIL_RE.test(v)) return v; } return ''; };
const val = (r, c) => String((c && r[c]) ?? '').trim();

const eligible = rows.filter(r => getEmail(r) && !val(r, statusCol) && val(r, subjectCol) && val(r, bodyCol));
if (eligible.length === 0) {
  return [{ json: { nothing_to_send: true, reason: 'No row has an email address AND an empty status.',
    rows_with_email: rows.filter(getEmail).length, rows_with_status_filled: rows.filter(r => val(r, statusCol)).length, ...diagnostics } }];
}
const r = eligible[0];
return [{ json: { row_number: r.row_number, status_column: statusCol, Company: val(r, companyCol),
  Email: getEmail(r), Subject: val(r, subjectCol), Body: val(r, bodyCol), remaining_after_this: eligible.length - 1 } }];

const p = $('Pick Next Prospect').first().json;
const err = $json.error ? ($json.error.message || JSON.stringify($json.error)) : 'send error';
return [{ json: { row_number: p.row_number, [p.status_column]: 'Failed ' + $now.toFormat('yyyy-LL-dd HH:mm') + ': ' + String(err).slice(0, 200) } }];
